/* ── welcome stats ───────────────────────────────────────────── */
document.getElementById('welcomeStats').innerHTML = `
  <div><b>${D.nodes.length.toLocaleString()}</b>items</div>
  <div><b>${D.recipes.length.toLocaleString()}</b>recipes</div>
  <div><b>${D.spells.length}</b>spells</div>
  <div><b>${D.skills.length}</b>skills</div>`;

/* ═══════════════════════════════════════════════════════════════
   POSSESSIONS — mark what you have, walk the atlas as unlocked
   ═══════════════════════════════════════════════════════════════ */

function persistOwned() {
  localStorage.setItem('dw.owned', JSON.stringify([...owned]));
  ownedCountEl.textContent = owned.size;
  ownedCountEl.classList.toggle('has', owned.size > 0);
}
const ownedCountEl = document.getElementById('ownedCount');

function propagateReach() {
  // walk forward from owned nodes through recipe + skill edges
  const reach = new Set();
  const stack = [...owned];
  while (stack.length) {
    const cur = stack.pop();
    if (reach.has(cur)) continue;
    reach.add(cur);
    for (const e of D.edges) {
      if (e.from === cur && !reach.has(e.to)) stack.push(e.to);
    }
  }
  return reach;
}

function applyPossessions() {
  if (!focusOwned) {
    cy.batch(() => {
      cy.nodes().removeClass('locked reachable');
      cy.edges().removeClass('locked reachable');
      applyCategoryVisibility();
    });
    updateReadout();
    if (!isolatedRoot) fitSoon();
    return;
  }
  const reach = propagateReach();
  cy.batch(() => {
    cy.nodes().forEach(n => {
      const id = n.id();
      n.removeClass('locked reachable');
      if (owned.has(id)) n.addClass('reachable');
      else if (reach.has(id)) n.addClass('reachable');
      else if (!n.hasClass('hidden')) n.addClass('locked');
    });
    cy.edges().forEach(e => {
      e.removeClass('locked reachable');
      const s = e.source().id(), t = e.target().id();
      if (reach.has(t) && (owned.has(s) || reach.has(s))) e.addClass('reachable');
      else if (!e.source().hasClass('hidden') && !e.target().hasClass('hidden')) e.addClass('locked');
    });
    applyCategoryVisibility();
  });
  updateReadout();
}

/* ── selection / isolation / panel ──────────────────────────── */

function selectNode(id, { fly = true } = {}) {
  document.getElementById('welcome').classList.add('hidden');
  selectedId = id;
  const n0 = nodeById.get(id);
  if (n0 && showOrphans === false) {
    const el = cy.getElementById(id);
    if (el.length && el.hasClass('orphan')) {
      showOrphans = true;
      document.getElementById('orphansChip').classList.add('on');
      applyCategoryVisibility();
    }
  }
  const n = cy.getElementById(id);
  if (!n || n.length === 0) return;
  cy.elements().removeClass('sel traced faded');
  cy.getElementById(id).addClass('sel');
  if (fly) cy.animate({ center: { eles: n }, zoom: Math.max(cy.zoom(), 1.1) }, { duration: 420 });
  openPanel(id);
  updateBreadcrumb();
}

function clearIsolation() {
  isolatedRoot = null;
  tracedId = null;
  cy.batch(() => {
    cy.nodes().removeClass('hidden traced').style({ opacity: '' });
    cy.edges().removeClass('hidden traced').style({ opacity: '' });
    applyCategoryVisibility();
  });
  document.getElementById('breadcrumb').classList.add('hidden');
  fitSoon();
}

function isolateTree(id, depthOverride = null) {
  // depth: number of recipe steps up & down (1 = direct neighbors only);
  // empty input = unlimited (full tree to the leaves)
  const dEl = document.getElementById('isoDepth');
  const raw = depthOverride !== null ? depthOverride
    : (dEl && dEl.value !== '' ? Math.max(1, parseInt(dEl.value, 10) || 3) : Infinity);
  if (dEl) localStorage.setItem('dw.isoDepth', dEl.value);
  // P4-3 prototype: direction-dominant walk. The both-direction walk-to-leaves
  // pulls in nearly the whole graph for hub items (bars/logs) — 'outputs only'
  // answers "what does this enable", 'inputs only' answers "what does this need".
  const dirEl = document.getElementById('isoDir');
  const dir = dirEl ? dirEl.value : 'both'; // both | down | up
  if (dirEl) localStorage.setItem('dw.isoDir', dir);
  isolatedRoot = id;
  // breadth-first over recipe edges, up to `raw` steps (or until leaves),
  // honouring the chosen direction
  const keep = new Map([[id, 0]]);
  let frontier = [id];
  let d = 0;
  while (frontier.length && d < raw) {
    const next = [];
    for (const cur of frontier) {
      for (const e of D.edges) {
        let nb = null;
        if (dir !== 'up' && e.from === cur) nb = e.to;         // outputs: what this makes/enables
        else if (dir !== 'down' && e.to === cur) nb = e.from;  // inputs: what this needs
        if (nb !== null && !keep.has(nb)) { keep.set(nb, d + 1); next.push(nb); }
      }
    }
    frontier = next;
    d++;
  }
  cy.batch(() => {
    // auto-reveal every kind so the tree is fully visible regardless of filters
    for (const k of Object.keys(kindLabel)) activeCats.add(k);
    document.querySelectorAll('.chip[data-cat]').forEach(c => c.classList.add('on'));
    showOrphans = false;
    document.getElementById('orphansChip').classList.remove('on');
    cy.nodes().forEach(n => {
      if (!keep.has(n.id())) n.addClass('hidden');
      else n.removeClass('hidden');
    });
    cy.edges().forEach(e => {
      if (keep.has(e.source().id()) && keep.has(e.target().id())) e.removeClass('hidden');
      else e.addClass('hidden');
    });
  });
  selectNode(id, { fly: false });
  setTimeout(() => cy.fit(undefined, 70), 60);
  const dirLabel = dir === 'down' ? 'outputs only' : dir === 'up' ? 'inputs only' : 'inputs + outputs';
  toast(`Crafting tree of ${nodeById.get(id).name} · ${dirLabel} · depth ${raw === Infinity ? 'all' : raw} · ${keep.size - 1} items`);
}

function traceInputs(id) {
  tracedId = id;
  const keep = new Set([id]);
  const stack = [id];
  while (stack.length) {
    const cur = stack.pop();
    for (const e of D.edges) {
      if (e.to === cur && !keep.has(e.from)) { keep.add(e.from); stack.push(e.from); }
    }
  }
  cy.batch(() => {
    cy.elements().addClass('faded');
    cy.nodes().forEach(n => { if (keep.has(n.id())) n.removeClass('faded').addClass('traced'); });
    cy.edges().forEach(e => {
      if (keep.has(e.source().id()) && keep.has(e.target().id())) e.removeClass('faded').addClass('traced');
    });
  });
  toast(`Inputs of ${nodeById.get(id).name} highlighted`);
}

// forward trace (P4-2): everything this item feeds into — recipes it is an
// ingredient of, plus whatever those outputs go on to make
function traceOutputs(id) {
  tracedId = id;
  const keep = new Set([id]);
  const stack = [id];
  while (stack.length) {
    const cur = stack.pop();
    for (const e of D.edges) {
      if (e.from === cur && !keep.has(e.to)) { keep.add(e.to); stack.push(e.to); }
    }
  }
  const direct = new Set(D.edges.filter(e => e.from === id).map(e => e.to));
  cy.batch(() => {
    cy.elements().addClass('faded');
    cy.nodes().forEach(n => { if (keep.has(n.id())) n.removeClass('faded').addClass('traced'); });
    cy.edges().forEach(e => {
      if (keep.has(e.source().id()) && keep.has(e.target().id())) e.removeClass('faded').addClass('traced');
    });
  });
  toast(`Everything ${nodeById.get(id).name} makes: ${direct.size} direct, ${keep.size - 1} total downstream`);
}

function clearTrace() {
  tracedId = null;
  cy.elements().removeClass('faded traced');
}

/* ── "From nothing" planner + two-node path query ───────────── */

// Recipes indexed by output, in wiki order (first non-deprecated = primary)
const recipesByOut = (() => {
  const m = new Map();
  for (const r of D.recipes) { if (!m.has(r.output)) m.set(r.output, []); m.get(r.output).push(r); }
  return m;
})();

// Walk the (primary) recipe tree of `id` down to raw materials, multiplying
// quantities. Collects: leaf mats, stations needed, skills (+levels), and — for
// the waypoint checklist — every non-owned item on the remaining tree with its
// craft/gather quantity. When plans start from the ledger (owned/waypoint
// modes), owned items satisfy subtrees: their quantities land in `have` instead
// of `mats`, and subtree expansion stops there.
let planMode = localStorage.getItem('dw.planMode')
  || (localStorage.getItem('dw.planUseOwned') !== '0' ? 'owned' : 'nothing'); // nothing | owned | waypoint

function walkPlan(id, useOwned) {
  const mats = new Map();       // material name -> qty still needed for one craft
  const have = new Map();       // material name -> qty already owned (owned mode)
  const stations = new Set();   // station names used anywhere up the tree
  const skillLv = new Map();    // skill name -> required level
  const needed = new Map();     // item -> { qty, kind: 'gather'|'craft'|'build', facility?, skill? }
  const inPath = new Set();     // cycle guard

  const primary = x => {
    const rs = recipesByOut.get(x);
    if (!rs || !rs.length) return null;
    return rs.find(r => !r.deprecated) || rs[0];
  };

  const visit = (x, mult) => {
    if (useOwned && owned.has(x)) { have.set(x, (have.get(x) || 0) + mult); return 0; }
    if (inPath.has(x)) { mats.set(x, (mats.get(x) || 0) + mult); return 0; }
    const r = primary(x);
    if (!r) {
      mats.set(x, (mats.get(x) || 0) + mult);
      const n = needed.get(x);
      needed.set(x, { qty: (n ? n.qty : 0) + mult, kind: 'gather' });
      return 0;
    }
    if (r.facility && nodeById.get(r.facility) && nodeById.get(r.facility).kind === 'station') stations.add(r.facility);
    if (r.skill) skillLv.set(r.skill, Math.max(skillLv.get(r.skill) || 1, 1));
    for (const g of (D.skillLevelForItem[x] || [])) skillLv.set(g.skill, Math.max(skillLv.get(g.skill) || 1, g.level || 1));
    inPath.add(x);
    const crafts = Math.max(1, Math.ceil(mult / (r.outputQty || 1)));
    let best = 0;
    for (const i of r.inputs) best = Math.max(best, visit(i.name, crafts * i.qty) + 1);
    inPath.delete(x);
    const n = needed.get(x);
    needed.set(x, { qty: (n ? n.qty : 0) + crafts, kind: 'craft', facility: r.facility || null, skill: r.skill || null });
    return best;
  };

  const depth = visit(id, 1);
  const rootOwned = useOwned && owned.has(id);
  if (rootOwned) needed.delete(id);
  return { mats, have, stations, skillLv, depth, rootOwned, needed, primary };
}

function planFromNothing(id) {
  const useOwned = planMode !== 'nothing' && owned.size > 0;
  const w = walkPlan(id, useOwned);
  const { mats, have, depth, rootOwned } = w;
  // raw/gatherable root: it would just list itself as its own material — no plan
  // (unless you own it, in which case the plan is "done")
  if (!w.primary(id) && !rootOwned) return null;
  if (!mats.size && !have.size && !rootOwned) return null;
  const allOwned = rootOwned || (!mats.size && have.size > 0);

  // critical chain: follow the input with the longest upstream depth, root -> leaf.
  // With the ledger in play, the chain stops at the first owned anchor (that's where work resumes).
  function subDepth(x, seen) { // memo-free longest depth (primary-recipe trees are small)
    if (seen.has(x)) return 0;
    seen.add(x);
    const r = w.primary(x);
    if (!r) return 0;
    let m = 0;
    for (const i of r.inputs) m = Math.max(m, subDepth(i.name, seen) + 1);
    return m;
  }
  const chain = [];
  let cur = id, guard = 0;
  while (cur && guard++ < 64) {
    chain.push(cur);
    if (useOwned && owned.has(cur)) break; // owned anchor: progress starts here
    const r = w.primary(cur);
    if (!r || !r.inputs.length) break;
    let bestD = -1, bestIn = null;
    for (const i of r.inputs) {
      const d = subDepth(i.name, new Set());
      if (d > bestD) { bestD = d; bestIn = i.name; }
    }
    cur = bestIn;
  }
  return { mats, have, stations: w.stations, skillLv: w.skillLv, chain, depth, allOwned, useOwned };
}

// Waypoint checklist (PF-4): the remaining work as an ordered, checkable list
// from your possessions to the target. Kahn topological order over the needed
// items (inputs before outputs; gathers float to the top), with un-owned
// stations injected as "build" steps ahead of the crafts that use them.
// Per-target progress for the waypoint checklist (persisted): remembers the
// first step count seen for a target and how many check-off/uncheck/re-plan
// cycles happened since. `wpReset(id)` clears it.
function wpRecord(id) {
  const all = JSON.parse(localStorage.getItem('dw.wpProgress') || '{}');
  if (!all[id]) all[id] = { total: null, done: 0, replans: 0 };
  return all[id];
}
function wpSave(id, rec) {
  const all = JSON.parse(localStorage.getItem('dw.wpProgress') || '{}');
  all[id] = rec;
  localStorage.setItem('dw.wpProgress', JSON.stringify(all));
}
function wpReset(id) {
  const all = JSON.parse(localStorage.getItem('dw.wpProgress') || '{}');
  delete all[id];
  localStorage.setItem('dw.wpProgress', JSON.stringify(all));
}

function planChecklist(id) {
  const useOwned = planMode !== 'nothing' && owned.size > 0;
  const w = walkPlan(id, useOwned);
  if (w.rootOwned || !w.primary(id)) return { ...w, steps: [] };
  const need = w.needed;
  for (const [, info] of [...need]) { // inject un-owned stations (materials: see the station's panel)
    if (info.kind !== 'craft' || !info.facility) continue;
    const fNode = nodeById.get(info.facility);
    if (!fNode || fNode.kind !== 'station' || owned.has(info.facility) || need.has(info.facility)) continue;
    need.set(info.facility, { qty: 1, kind: 'build' });
  }
  const kindRank = k => (k === 'gather' ? 0 : 1);
  const outs = new Map();   // prerequisite -> [dependents]
  const indeg = new Map([...need.keys()].map(k => [k, 0]));
  for (const [x, info] of need) {
    if (info.kind !== 'craft') continue;
    const r = w.primary(x);
    for (const i of r.inputs) {
      if (!need.has(i.name) || i.name === x) continue;
      indeg.set(x, indeg.get(x) + 1);
      if (!outs.has(i.name)) outs.set(i.name, []);
      outs.get(i.name).push(x);
    }
    const f = info.facility;
    if (need.has(f) && f !== x) { // station must exist before its first use
      indeg.set(x, indeg.get(x) + 1);
      if (!outs.has(f)) outs.set(f, []);
      outs.get(f).push(x);
    }
  }
  const byKind = (a, b) => kindRank(need.get(a).kind) - kindRank(need.get(b).kind) || a.localeCompare(b);
  const ready = [...need.keys()].filter(k => indeg.get(k) === 0).sort(byKind);
  const order = [];
  while (ready.length) {
    const x = ready.shift();
    order.push(x);
    for (const y of (outs.get(x) || [])) {
      indeg.set(y, indeg.get(y) - 1);
      if (indeg.get(y) === 0) ready.push(y);
    }
    ready.sort(byKind);
  }
  for (const k of [...need.keys()].sort()) if (!order.includes(k)) order.push(k); // cycle fallback
  return { ...w, steps: order.map(name => ({ name, ...need.get(name) })) };
}

// --- path between nodes (BFS over material edges, skills excluded) ---
let pathFrom = null;      // source id while arming
let pathArming = false;
let pathOwnedMode = false; // arming seeded by the possessions ledger (PF-3)
let lastPath = null;      // { from, to, steps: [{from, to, e}], multi? }

function findPath(a, b) {
  // undirected adjacency over non-skill edges (skill gates are metadata, not steps)
  const adj = new Map();
  const push = (x, v) => { if (!adj.has(x)) adj.set(x, []); adj.get(x).push(v); };
  for (const e of D.edges) {
    if (SKILL_NAMES.has(e.from) || SKILL_NAMES.has(e.to)) continue;
    push(e.from, { to: e.to, e });
    push(e.to, { to: e.from, e });
  }
  // BFS from many sources at once (PF-3: everything you own); `a` may be a single id or a Set
  const sources = a instanceof Set ? [...a] : [a];
  const prev = new Map(sources.map(s => [s, null]));
  const q = [...sources];
  while (q.length) {
    const cur = q.shift();
    if (cur === b) break;
    for (const { to, e } of (adj.get(cur) || [])) {
      if (!prev.has(to)) { prev.set(to, { node: cur, e }); q.push(to); }
    }
  }
  if (!prev.has(b)) return null;
  const steps = [];
  for (let cur = b; prev.get(cur); cur = prev.get(cur).node) {
    const p = prev.get(cur);
    steps.unshift({ from: p.node, to: cur, e: p.e });
  }
  return steps;
}

// dedicated top bar for the armed path query (TODO #18) — visible from arming
// until the path is cleared, so the query state is never invisible
const pathbar = document.getElementById('pathbar');
function showPathbar(text, pulsing = true) {
  if (!pathbar) return;
  document.getElementById('pathbarText').textContent = text;
  pathbar.classList.remove('hidden');
  document.body.classList.toggle('path-result', !pulsing);
}
function hidePathbar() {
  if (pathbar) pathbar.classList.add('hidden');
  document.body.classList.remove('path-result');
}
if (pathbar) document.getElementById('pathbarCancel').onclick = () => { clearPath(); toast('Path query cancelled'); };

function armPath(id) {
  pathFrom = id;
  pathArming = true;
  document.body.classList.add('path-arming');
  searchInput.dataset.armed = '1';
  searchInput.placeholder = `Path from “${nodeById.get(id).name}” — pick or type the target…`;
  searchInput.classList.add('arming');
  showPathbar(`Path from “${nodeById.get(id).name}” — tap the target on the map, or pick it via search`);
  toast(`Path FROM ${nodeById.get(id).name} — tap the target on the map, or pick it via search (Esc cancels)`);
}

function disarmPath() {
  pathArming = false;
  pathFrom = null;
  pathOwnedMode = false;
  document.body.classList.remove('path-arming', 'path-arming-owned');
  delete searchInput.dataset.armed;
  searchInput.placeholder = 'Search items, stations, materials…';
  searchInput.classList.remove('arming');
  hidePathbar();
}

function clearPath() {
  lastPath = null;
  disarmPath();
  hidePathbar();
  cy.elements().removeClass('faded traced');
}

function runPath(a, b, multi = false) {
  disarmPath();
  const srcIds = multi ? [...a] : [a];
  if (!multi && a === b) { toast('Pick a different target — that is the same item'); return; }
  if (multi && srcIds.includes(b)) { toast('You already own the target — nothing to craft'); return; }
  const steps = findPath(multi ? new Set(srcIds) : a, b);
  if (!steps) {
    toast(multi
      ? `Nothing in your ledger leads to ${nodeById.get(b).name} — mark closer items as owned`
      : `No crafting path between ${nodeById.get(a).name} and ${nodeById.get(b).name}`);
    return;
  }
  lastPath = { from: multi ? srcIds : a, to: b, steps, multi };
  selectNode(b); // renders target panel (which shows the path section) and clears old classes
  cy.batch(() => {
    cy.elements().addClass('faded');
    for (const s of steps) {
      cy.getElementById(s.from).removeClass('faded').addClass('traced');
      cy.getElementById(s.to).removeClass('faded').addClass('traced');
      const eid = s.e.from + '→' + s.e.to + ':' + s.e.qty + (s.e.variant ? ':' + s.e.variant : '');
      cy.getElementById(eid).removeClass('faded').addClass('traced');
    }
  });
  const fromTxt = multi
    ? `${srcIds.length} owned item${srcIds.length > 1 ? 's' : ''}`
    : nodeById.get(a).name;
  showPathbar(`Path: ${fromTxt} → ${nodeById.get(b).name} · ${steps.length} step${steps.length > 1 ? 's' : ''}`, false);
  toast(`Path: ${steps.length} step${steps.length > 1 ? 's' : ''} from ${fromTxt} to ${nodeById.get(b).name}`);
}

// PF-3: path seeded with every item in the possessions ledger
function runPathOwned(b) {
  if (!owned.size) { toast('Mark items as owned first (✓ Owned in their panel)'); return; }
  runPath(new Set(owned), b, true);
}

// PF-3: arm a path query whose source is the whole ledger; next tap = target
function armPathOwned() {
  if (!owned.size) { toast('Mark items as owned first (✓ Owned in their panel)'); return; }
  pathFrom = null;
  pathOwnedMode = true;
  pathArming = true;
  document.body.classList.add('path-arming', 'path-arming-owned');
  searchInput.dataset.armed = '1';
  searchInput.placeholder = `Path from your ${owned.size} owned item${owned.size > 1 ? 's' : ''} — pick the target…`;
  searchInput.classList.add('arming');
  showPathbar(`Path from your ${owned.size} owned item${owned.size > 1 ? 's' : ''} — tap the target on the map, or pick it via search`);
  toast(`Path FROM your ${owned.size} owned item${owned.size > 1 ? 's' : ''} — tap the target (Esc cancels)`);
}

function pathStepsHTML(p) {
  const fromTxt = p.multi
    ? `your ${p.from.length} owned item${p.from.length > 1 ? 's' : ''}`
    : nodeById.get(p.from).name;
  const rows = p.steps.map((s, i) => {
    const qty = s.e.qty ? `<span class="q">${s.e.qty}×</span> ` : '';
    const fac = s.e.facility && s.e.facility !== 'Cast' ? `<span class="pstep-fac">${esc(s.e.facility)}</span>` : '';
    return `<div class="path-step" data-goto="${esc(s.to)}">
      <span class="pn">${i + 1}</span>${iconImg(s.from)}<span class="ptx">${qty}${esc(s.from)}</span>
      <span class="arr">→</span>${fac}${iconImg(s.to)}<span class="ptx">${esc(s.to)}</span>
    </div>`;
  }).join('');
  return `<div class="p-section"><div class="p-label">Path from ${esc(fromTxt)} (${p.steps.length} steps)
    <button class="p-clear" id="btnClearPath" title="Clear path">✕</button></div>${rows}
    <div class="p-hint">Gold trail = the shortest material route. Esc also clears.</div></div>`;
}

/* ── canvas events ───────────────────────────────────────────── */
cy.on('tap', 'node', (evt) => {
  const id = evt.target.id();
  closeSuggestions();
  const oe = evt.originalEvent || {};
  if (pathArming) {
    if (pathOwnedMode) { if (!owned.has(id)) { runPathOwned(id); return; } }
    else if (pathFrom && id !== pathFrom) { runPath(pathFrom, id); return; }
  }
  if (oe.shiftKey) { isolateTree(id); return; }
  selectNode(id);
});
cy.on('tap', (evt) => {
  if (evt.target === cy) { document.getElementById('welcome').classList.add('hidden'); closePanel(); clearTrace(); }
});

let hoverTimer = null;
let hovered = null;
cy.on('mouseover', 'node', (evt) => {
  clearTimeout(hoverTimer);
  hoverTimer = setTimeout(() => {
    if (tracedId || isolatedRoot) return;
    hovered = evt.target;
    evt.target.neighborhood().union(evt.target).addClass('hoverN');
  }, 100);
});
cy.on('mouseout', 'node', () => {
  clearTimeout(hoverTimer);
  if (hovered) { cy.elements().removeClass('hoverN'); hovered = null; }
});

/* ── panel ───────────────────────────────────────────────────── */
const panel = document.getElementById('panel');
const panelBody = document.getElementById('panelBody');

function iconImg(id, cls = '') {
  const n = nodeById.get(id);
  if (n && n.icon) return `<img src="${n.icon}" alt="" loading="lazy" class="${cls}">`;
  return `<span class="p-glyph" style="display:grid;place-items:center;width:100%;height:100%">${kindGlyph[n ? n.kind : 'other'] || '✦'}</span>`;
}

function esc(s) { return String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }

function facilityIcon(facility) {
  const st = D.nodes.find(n => n.id === facility && n.kind === 'station');
  return st && st.icon ? `<img src="${st.icon}" alt="">` : '';
}

function openPanel(id) {
  const n = nodeById.get(id);
  if (!n) return;
  const sp = D.spells.find(s => s.name === id);
  document.getElementById('panelTitle').textContent = n.name;
  document.getElementById('panelType').textContent = n.kind === 'skill'
    ? 'Skill'
    : (n.kind === 'spell' && sp
      ? `Spell · ${sp.skill || '?'}${sp.level ? ' lvl ' + sp.level : ''}`
      : (n.itemType || kindLabel[n.kind] || n.kind) +
        (inDegree.get(id) ? ` · made by ${inDegree.get(id)} recipe${inDegree.get(id) > 1 ? 's' : ''}` : '') +
        (outDegree.get(id) ? ` · used in ${outDegree.get(id)}` : ''));
  document.getElementById('panelIcon').innerHTML = iconImg(id);
  renderPanelBody(n);
  panel.classList.add('open');
}

function closePanel() {
  panel.classList.remove('open');
  selectedId = null;
  cy.elements().removeClass('sel');
  updateBreadcrumb();
}

document.getElementById('panelClose').onclick = closePanel;

function ownedBtnHTML(id) {
  const has = owned.has(id);
  return `<button class="btn ${has ? 'primary' : ''}" id="btnOwn" data-owned="${has}">${has ? '✓ Owned' : '☆ Mark owned'}</button>`;
}

function renderPanelBody(n) {
  const id = n.id;
  const recipesIn = D.recipes.filter(r => r.output === id);
  const usedIn = D.edges.filter(e => e.from === id && !SKILL_NAMES.has(e.from));
  const spell = D.spells.find(s => s.name === id);
  const skill = D.skills.find(s => s.name === id);
  const unlocks = D.skillLevelForItem[id] || [];

  const sections = [];

  // region pseudo-node (P4-1b): what is found here, jumpable
  if (n.kind === 'region') {
    const members = regionMembers.get(id) || new Map();
    const verb = { mined: 'mined', chopped: 'chopped', picked: 'picked', farmed: 'farmed', caught: 'fished', drops: 'drops', chest: 'in chests', dungeon: 'in dungeons', other: 'found' };
    const rows = [...members.entries()].sort((a, b) => a[0].localeCompare(b[0])).map(([item, methods]) =>
      `<div class="found-row fi-jump" data-goto="${esc(item)}">${iconImg(item)}<span class="fr">${esc(item)}</span><span class="fw">${[...methods].map(m => esc(verb[m] || m)).join(' · ')}</span></div>`
    ).join('');
    sections.push(`<div class="p-section"><div class="p-label">What you find here (${members.size})</div>${rows}</div>`);
    sections.push(`<div class="p-section"><div class="p-hint">Region hubs are map aids mined from the wiki's location prose — recipes and plans ignore them. Toggle their green links in the legend (LINKS → Region links).</div></div>`);
    panelBody.innerHTML = sections.join('');
    panelBody.scrollTop = 0;
    panelBody.querySelectorAll('[data-goto]').forEach(el => { el.onclick = () => selectNode(el.dataset.goto); });
    return;
  }

  // "From nothing" plan — the atlas' core question; shown for items and raw
  // resources alike (raw items get the Path-to query instead of a plan).
  // PF-3: with the ledger populated, plans can start from what you own.
  const isSkillOrSpell = n.kind === 'skill' || n.kind === 'spell';
  const plan = isSkillOrSpell ? null : planFromNothing(id);
  const wp = !isSkillOrSpell && planMode === 'waypoint' && owned.size > 0 ? planChecklist(id) : null;
  const ownedModeOn = plan && plan.useOwned;
  const planTitle = wp ? 'Waypoint checklist' : ownedModeOn ? 'From what you own — remaining' : 'From nothing — what you need';
  const modeBtnLabel = wp ? 'plan: waypoint' : ownedModeOn ? 'plan: owned' : 'plan: nothing';
  const planBtns = `<button class="p-clear gold" id="btnPathTo" title="Find the shortest material path from another item to this one">Path to…</button>${
    owned.size ? `<button class="p-clear" id="btnPlanMode" title="Cycle plans: from nothing → from your owned items → waypoint checklist (check steps off as you craft them)">${modeBtnLabel}</button>` : ''}`;
  if (plan) {
    if (wp && wp.steps.length) {
      // progress record: remember the original step count, count re-plans
      const rec = wpRecord(id);
      if (rec.total === null) { rec.total = wp.steps.length; wpSave(id, rec); }
      const done = Math.max(0, rec.total - wp.steps.length);
      const stepRows = wp.steps.map(s => {
        const verb = s.kind === 'gather' ? 'Gather' : s.kind === 'build' ? 'Build' : 'Craft';
        const fac = s.kind === 'craft' && s.facility ? ` — ${s.facility}` : '';
        return `<div class="wp-step" data-step="${esc(s.name)}"><span class="wp-box" title="Mark ${esc(s.name)} owned"></span>${iconImg(s.name)}<span class="wp-verb">${verb}</span><span class="wp-qty">${s.qty}×</span><span class="mn" data-goto="${esc(s.name)}">${esc(s.name)}</span><span class="wp-fac">${esc(fac)}</span></div>`;
      }).join('');
      const progress = `<div class="wp-progress"><span class="wp-count"><b>${done}</b> of <b>${rec.total}</b> steps done</span><span class="wp-replans" title="How many times the checklist re-planned (check-offs, ledger edits)">· ${rec.replans} re-plan${rec.replans === 1 ? '' : 's'}</span><span style="flex:1"></span><button class="p-clear" id="btnWpReset" title="Clear the progress record for this item (does not unmark owned items)">reset</button></div>`;
      sections.push(`<div class="p-section plan owned-mode waypoint">
        <div class="p-label">${planTitle}<span style="flex:1"></span>${planBtns}</div>
        ${progress}
        <div class="p-hint" style="margin-bottom:6px">Work top to bottom. Checking a step adds it to your ledger and re-plans from what you'll own.</div>
        <div class="wp-list">${stepRows}</div>
      </div>`);
    } else {
    const matChips = [...plan.mats.entries()].sort((a, b) => b[1] - a[1]).map(([m, q]) =>
      `<span class="mat" data-goto="${esc(m)}">${iconImg(m)}<span class="q">${q}×</span><span class="mn">${esc(m)}</span></span>`).join('');
    const haveChips = plan.useOwned && plan.have.size ? [...plan.have.entries()].sort((a, b) => b[1] - a[1]).map(([m, q]) =>
      `<span class="mat owned" data-goto="${esc(m)}">${iconImg(m)}<span class="q">${q}×</span><span class="mn">${esc(m)}</span></span>`).join('') : '';
    const stChips = [...plan.stations].map(s =>
      `<span class="mat${owned.has(s) ? ' owned' : ''}" data-goto="${esc(s)}">${iconImg(s)}<span class="mn">${esc(s)}</span></span>`).join('');
    const skChips = [...plan.skillLv.entries()].map(([s, lv]) =>
      `<span class="mat sk" data-goto="${esc(s)}">${skillIcon(s)}<span class="mn">${esc(s)} ${lv}</span></span>`).join('');
    const chainHTML = plan.chain.filter(Boolean).map((c, i) =>
      `${i ? '<span class="arr">→</span>' : ''}<span class="mat${owned.has(c) ? ' owned' : ''}" data-goto="${esc(c)}">${iconImg(c)}<span class="mn">${esc(c)}</span></span>`).join('');
    sections.push(`<div class="p-section plan${ownedModeOn ? ' owned-mode' : ''}">
      <div class="p-label">${planTitle}<span style="flex:1"></span>${planBtns}</div>
      ${plan.allOwned ? '<div class="p-hint" style="margin-bottom:6px">✓ You can make this from your ledger — nothing left to gather.</div>' : ''}
      ${matChips ? `<div class="p-label sub">Gather</div><div class="recipe-mats">${matChips}</div>` : ''}
      ${haveChips ? `<div class="p-label sub">Already own</div><div class="recipe-mats">${haveChips}</div>` : ''}
      ${stChips ? `<div class="p-label sub">Build${ownedModeOn && plan.stations.size && [...plan.stations].every(s => owned.has(s)) ? ' — have them all' : ''}</div><div class="recipe-mats">${stChips}</div>` : ''}
      ${skChips ? `<div class="p-label sub">Train</div><div class="recipe-mats">${skChips}</div>` : ''}
      ${chainHTML ? `<div class="p-label sub">Critical chain (${plan.depth} steps)</div><div class="recipe-mats">${chainHTML}</div>` : ''}
    </div>`);
    }
  } else if (n.kind !== 'skill' && n.kind !== 'spell') {
    sections.push(`<div class="p-section plan">
      <div class="p-label">From nothing<span style="flex:1"></span>${planBtns}</div>
      ${owned.size && !owned.has(id) ? `<div class="p-hint" style="margin-bottom:6px"><button class="p-clear gold" id="btnPathOwned" title="Find the shortest crafting route starting from anything in your ledger">From owned → this</button> finds a route from your ${owned.size} owned item${owned.size > 1 ? 's' : ''}.</div>` : ''}
      <div class="p-hint">Raw or gathered item — nothing to craft. Use “Path to…” to find the shortest route from this item to any other.</div>
    </div>`);
  }

  // two-node path result (only when this node is the target of a queried path)
  if (lastPath && lastPath.to === id) sections.push(pathStepsHTML(lastPath));

  // description
  if (n.description && n.description.length) {
    sections.push(`<div class="p-section"><div class="p-label">Description</div>
      <div class="p-desc">${n.description.map(esc).join('<br>')}</div></div>`);
  }

  // stats
  if (n.stats && Object.keys(n.stats).length) {
    const statLabel = { power: 'Power', basedmg: 'Base dmg', damagetype: 'Type', meleedefence: 'Melee def', rangeddefence: 'Ranged def', magicdefence: 'Magic def', durability: 'Durability', block: 'Block', health: 'Health', hydration: 'Hydration', sustenance: 'Sustenance', weight: 'Weight' };
    sections.push(`<div class="p-section"><div class="p-label">Stats</div><div class="p-stats">${
      Object.entries(n.stats).map(([k, v]) =>
        `<div class="p-stat"><div class="v">${esc(v)}</div><div class="k">${esc(statLabel[k] || k)}</div></div>`).join('')
    }</div></div>`);
  }

  // skill hub panel: its unlock ladder (only meaningful unlocks)
  if (skill) {
    const rows = skill.unlocks.filter(u => u.text && !/^-[\d.]+%/.test(u.text) && u.text !== '-').map(u =>
      `<div class="unlock-row"><span class="lvl">${u.level}</span><span class="utx">${esc(u.text)}</span></div>`).join('');
    if (rows) sections.push(`<div class="p-section"><div class="p-label">Level unlocks</div>${rows}</div>`);
  }

  // spells: rune requirements + skill gate
  if (spell) {
    const runes = Object.entries(spell.runes || {});
    sections.push(`<div class="p-section"><div class="p-label">Spell</div>
      <div class="p-stats" style="grid-template-columns:repeat(2,1fr)">
        <div class="p-stat"><div class="v">${esc(spell.skill || '—')}${spell.level ? ' · lvl ' + spell.level : ''}</div><div class="k">Requires</div></div>
        <div class="p-stat"><div class="v">${esc(spell.cooldown || '—')}</div><div class="k">Cooldown</div></div>
      </div>
      ${runes.length ? `<div class="p-label" style="margin-top:10px">Cast cost</div><div class="recipe-mats">${runes.map(([r, q]) => {
        let rn = /rune$/i.test(r) ? r : r + ' Rune';
        if (!nodeById.get(rn)) rn = rn.replace(/\bRune\b/i, 'rune');
        return `<span class="mat" data-goto="${esc(rn)}">${iconImg(rn)}${esc(r)} × ${esc(q)}</span>`;
      }).join('')}</div>` : ''}
      ${spell.description && spell.description.length ? `<div class="p-desc" style="margin-top:8px">${spell.description.map(esc).join('<br>')}</div>` : ''}
    </div>`);
  }

  // skill gates on this item
  if (unlocks.length) {
    sections.push(`<div class="p-section"><div class="p-label">Skill gates</div>${
      unlocks.map(u => `<div class="unlock-row"><span class="lvl">${u.level}</span><span class="utx">${esc(u.skill)} ${u.level} — ${esc(u.text)}</span></div>`).join('')
    }</div>`);
  }

  // recipes producing this item — facility is clickable
  if (recipesIn.length) {
    sections.push(`<div class="p-section"><div class="p-label">How to make ${recipesIn.length > 1 ? `(${recipesIn.length} ways)` : ''}</div>${
      recipesIn.map(r => recipeCard(r)).join('')
    }</div>`);
  }

  // found in — regions, gather method and tool (P4-1); rows jump to the region
  // pseudo-node (P4-1b), which now always exists for canonical regions
  if (foundIn.get(id)) {
    const byRegion = new Map();
    for (const f of foundIn.get(id)) {
      if (!byRegion.has(f.region)) byRegion.set(f.region, []);
      byRegion.get(f.region).push(f);
    }
    const verb = { mined: 'Mined', chopped: 'Chopped', picked: 'Picked up', farmed: 'Farmed', caught: 'Fished', drops: 'Drops from', chest: 'Chest', dungeon: 'Dungeon', shop: 'Bought', other: 'Found' };
    const rows = [...byRegion.entries()].sort((a, b) => a[0].localeCompare(b[0])).map(([region, list]) => {
      const ways = list.map(f => {
        const tool = f.tool ? ` with a <b class="fi-tool">${esc(f.tool)}</b>` : '';
        return `<span class="fi-way">${esc(verb[f.method] || f.method)}${tool}</span>`;
      }).join('<span class="fi-or"> · </span>');
      const row = document.getElementById('cy') ? cy.getElementById(region) : null;
      const clickable = row && row.nonempty();
      return `<div class="found-row${clickable ? ' fi-jump" data-goto="' + esc(region) + '"' : ''}">${iconImg(region) || '<span class="fi-pin">⌖</span>'}<span class="fr">${esc(region)}</span><span class="fw">${ways}</span></div>`;
    }).join('');
    sections.push(`<div class="p-section"><div class="p-label">Found in (${byRegion.size})</div>${rows}</div>`);
  }

  // used in
  if (usedIn.length) {
    const byOut = new Map();
    for (const e of usedIn) {
      if (!byOut.has(e.to)) byOut.set(e.to, []);
      byOut.get(e.to).push(e);
    }
    const rows = [...byOut.entries()].sort((a, b) => a[0].localeCompare(b[0])).map(([out, es]) =>
      `<div class="used-row" data-goto="${esc(out)}">${iconImg(out)}<span class="un">${esc(out)}</span><span class="uout">${es.map(e => '×' + e.qty + (e.facility ? ' ' + e.facility : '')).join(', ')}</span></div>`
    ).join('');
    sections.push(`<div class="p-section"><div class="p-label">Used to make (${byOut.size})</div>${rows}</div>`);
  }

  // direct materials of the first recipe
  if (recipesIn.length && recipesIn[0].inputs.length) {
    sections.push(`<div class="p-section"><div class="p-label">Direct materials</div><div class="recipe-mats">${
      recipesIn[0].inputs.map(i => `<span class="mat" data-goto="${esc(i.name)}">${iconImg(i.name)}<span class="q">${i.qty}×</span><span class="mn">${esc(i.name)}</span></span>`).join('')
    }</div></div>`);
  }

  // actions
  sections.push(`<div class="p-section p-actions">
    ${ownedBtnHTML(id)}
    <button class="btn" id="btnTrace">Trace inputs</button>
    <button class="btn" id="btnTraceOut" title="Highlight everything this item is used to make, directly or downstream">Trace makes ⤴</button>
    <button class="btn primary" id="btnIsolate">Isolate tree</button>
    <input id="isoDepth" type="number" min="1" step="1" placeholder="all" title="How many recipe steps up & down to include. Empty = the whole tree."
           style="width:74px;flex:0 0 auto" />
    <select id="isoDir" title="Direction-dominant isolation (P4-3): the full up+down walk can swallow nearly the whole map for hub items — outputs only answers 'what does this enable', inputs only answers 'what does this need'."
            style="width:104px;flex:0 0 auto">
      <option value="both">up + down</option>
      <option value="down">outputs only</option>
      <option value="up">inputs only</option>
    </select>
  </div>
  <div class="p-section p-actions">
    ${n.wiki ? `<a class="btn" href="${n.wiki}" target="_blank" rel="noopener">Wiki page ↗</a>` : ''}
  </div>`);

  panelBody.innerHTML = sections.join('');
  panelBody.scrollTop = 0;

  // wire actions
  panelBody.querySelectorAll('[data-goto]').forEach(el => {
    el.onclick = () => { selectNode(el.dataset.goto); };
  });
  const bt = document.getElementById('btnTrace');
  if (bt) bt.onclick = () => traceInputs(id);
  const bto = document.getElementById('btnTraceOut');
  if (bto) bto.onclick = () => traceOutputs(id);
  const bpt = document.getElementById('btnPathTo');
  if (bpt) bpt.onclick = () => armPath(id);
  const bpm = document.getElementById('btnPlanMode');
  if (bpm) bpm.onclick = () => {
    planMode = planMode === 'nothing' ? 'owned' : planMode === 'owned' ? 'waypoint' : 'nothing';
    localStorage.setItem('dw.planMode', planMode);
    renderPanelBody(n);
    toast(planMode === 'owned'
      ? `Plan starts from your ${owned.size} owned item${owned.size > 1 ? 's' : ''}`
      : planMode === 'waypoint'
        ? 'Waypoint checklist — check steps off as you craft them'
        : 'Plan starts from nothing');
  };
  const bpo = document.getElementById('btnPathOwned');
  if (bpo) bpo.onclick = () => armPathOwned();
  panelBody.querySelectorAll('.wp-box').forEach(box => {
    box.onclick = () => {
      const name = box.closest('.wp-step').dataset.step;
      const wasOwned = owned.has(name);
      if (wasOwned) owned.delete(name); else owned.add(name);
      persistOwned();
      applyPossessions();
      const rec = wpRecord(id);
      rec.replans++;
      if (!wasOwned) rec.done++;
      wpSave(id, rec);
      renderPanelBody(n);
      toast(wasOwned ? `Unmarked: ${name}` : `Marked owned: ${name}`);
    };
  });
  const bwr = document.getElementById('btnWpReset');
  if (bwr) bwr.onclick = () => { wpReset(id); renderPanelBody(n); toast('Waypoint progress reset'); };
  const bcp = document.getElementById('btnClearPath');
  if (bcp) bcp.onclick = () => { clearPath(); renderPanelBody(n); };
  const bi = document.getElementById('btnIsolate');
  if (bi) {
    bi.onclick = () => isolateTree(id);
    const dEl = document.getElementById('isoDepth');
    if (dEl) {
      dEl.value = localStorage.getItem('dw.isoDepth') ?? '';
      dEl.onkeydown = ev => { if (ev.key === 'Enter') { ev.preventDefault(); isolateTree(id); } };
    }
    const dirEl = document.getElementById('isoDir');
    if (dirEl) {
      const saved = localStorage.getItem('dw.isoDir');
      if (saved === 'down' || saved === 'up' || saved === 'both') dirEl.value = saved;
      dirEl.onchange = () => localStorage.setItem('dw.isoDir', dirEl.value);
    }
  }
  const bo = document.getElementById('btnOwn');
  if (bo) bo.onclick = () => {
    if (owned.has(id)) owned.delete(id); else owned.add(id);
    persistOwned();
    applyPossessions();
    renderPanelBody(n);
    toast(owned.has(id) ? `Marked owned: ${n.name}` : `Unmarked: ${n.name}`);
  };
}

function recipeCard(r) {
  const facility = r.facility || (r.blueprint ? r.blueprint : '—');
  const variant = r.variant && r.variant.toLowerCase() !== String(facility).toLowerCase() ? r.variant : null;
  // facilities that match a known station node become clickable
  const facNode = facility !== '—' && nodeById.get(facility);
  const facHTML = facNode
    ? `<span class="recipe-facility fac-link" data-goto="${esc(facNode.id)}">${facilityIcon(facNode.id)}${esc(facNode.name)}</span>`
    : `<span class="recipe-facility">${esc(facility)}</span>`;
  return `<div class="recipe ${r.deprecated ? 'deprecated' : ''}">
    <div class="recipe-head">
      ${facHTML}
      ${variant ? `<span class="recipe-variant">${esc(variant)}</span>` : ''}
      ${r.skill ? `<span class="recipe-skill" ${SKILL_NAMES.has(r.skill) ? `data-goto="${esc(r.skill)}" style="cursor:pointer"` : ''}>${skillIcon(r.skill)}${esc(r.skill)}${r.xp ? ' +' + r.xp + 'xp' : ''}</span>` : ''}
    </div>
    <div class="recipe-mats">${r.inputs.map(i =>
      `<span class="mat" data-goto="${esc(i.name)}">${iconImg(i.name)}<span class="q">${i.qty}×</span><span class="mn">${esc(i.name)}</span></span>`
    ).join('')}</div>
    ${r.notes && r.notes.length ? `<div class="recipe-notes">${r.notes.map(esc).join(' · ')}</div>` : ''}
  </div>`;
}

function skillIcon(name) {
  const s = D.skills.find(x => x.name === name);
  return s && s.icon ? `<img src="${s.icon}" alt="">` : '';
}

/* ── breadcrumb ──────────────────────────────────────────────── */
function updateBreadcrumb() {
  const bc = document.getElementById('breadcrumb');
  if (!isolatedRoot) { bc.classList.add('hidden'); return; }
  const chain = [];
  let cur = selectedId;
  const guard = new Set();
  while (cur && !guard.has(cur)) {
    guard.add(cur);
    chain.push(cur);
    const e = D.edges.find(e => e.to === cur && !SKILL_NAMES.has(e.from));
    if (!e) break;
    cur = e.from;
  }
  chain.reverse();
  if (chain.length < 1) { bc.classList.add('hidden'); return; }
  bc.innerHTML = chain.map((c, i) =>
    `<a data-goto="${esc(c)}">${esc(nodeById.get(c)?.name || c)}</a>${i < chain.length - 1 ? '<span class="sep">←</span>' : ''}`
  ).join('');
  bc.classList.remove('hidden');
  bc.querySelectorAll('[data-goto]').forEach(a => a.onclick = () => selectNode(a.dataset.goto));
}

/* ═══════════════════════════════════════════════════════════════
   SEARCH
   ═══════════════════════════════════════════════════════════════ */
const searchInput = document.getElementById('search');
const suggestions = document.getElementById('suggestions');
const searchClear = document.getElementById('searchClear');
let sugIndex = -1;
let sugItems = [];

function closeSuggestions() {
  suggestions.classList.remove('open');
  sugIndex = -1;
}

function fuzzyScore(q, text) {
  const t = text.toLowerCase();
  if (t.startsWith(q)) return 1000 - t.length;
  const idx = t.indexOf(q);
  if (idx >= 0) return 700 - idx * 2 - t.length * 0.1;
  let ti = 0, score = 0, streak = 0;
  for (const ch of q) {
    const found = t.indexOf(ch, ti);
    if (found === -1) return -1;
    if (found === ti) streak++; else streak = 0;
    score += streak * 3 - (found - ti) * 0.2;
    ti = found + 1;
  }
  return score;
}

function highlight(text, q) {
  const i = text.toLowerCase().indexOf(q.toLowerCase());
  if (i === -1) return esc(text);
  return esc(text.slice(0, i)) + '<mark>' + esc(text.slice(i, i + q.length)) + '</mark>' + esc(text.slice(i + q.length));
}

searchInput.addEventListener('input', () => {
  const q = searchInput.value.trim();
  searchClear.style.display = q ? 'block' : 'none';
  if (q.length < 1) { closeSuggestions(); return; }
  const scored = [];
  for (const n of nodeById.values()) { // includes region pseudo-nodes (P4-1b)
    const s = fuzzyScore(q.toLowerCase(), n.name.toLowerCase());
    if (s > 0) scored.push([s, n]);
  }
  scored.sort((a, b) => b[0] - a[0]);
  sugItems = scored.slice(0, 30).map(x => x[1]);
  if (!sugItems.length) { closeSuggestions(); return; }
  suggestions.innerHTML = sugItems.map((n, i) => `
    <div class="sug-item" data-i="${i}">
      ${n.icon ? `<img src="${n.icon}" alt="">` : `<span class="sug-ico">${kindGlyph[n.kind] || '✦'}</span>`}
      <div class="sug-name">
        <div class="n">${highlight(n.name, q)}</div>
        <div class="t">${esc(kindLabel[n.kind] || n.kind)}${outDegree.get(n.id) ? ' · used in ' + outDegree.get(n.id) : ''}</div>
      </div>
    </div>`).join('');
  suggestions.classList.add('open');
  sugIndex = -1;
  suggestions.querySelectorAll('.sug-item').forEach(el => {
    el.onclick = () => {
      const n = sugItems[Number(el.dataset.i)];
      closeSuggestions();
      searchInput.value = n.name;
      searchClear.style.display = 'block';
      if (pathArming) {
        if (pathOwnedMode) { if (!owned.has(n.id)) { runPathOwned(n.id); searchInput.blur(); return; } }
        else if (pathFrom && n.id !== pathFrom) { runPath(pathFrom, n.id); searchInput.blur(); return; }
      }
      selectNode(n.id);
    };
  });
});

searchInput.addEventListener('keydown', (e) => {
  const items = suggestions.querySelectorAll('.sug-item');
  if (e.key === 'ArrowDown') { e.preventDefault(); sugIndex = Math.min(sugIndex + 1, items.length - 1); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); sugIndex = Math.max(sugIndex - 1, 0); }
  else if (e.key === 'Enter') {
    e.preventDefault();
    const pick = sugItems[Math.max(0, sugIndex)];
    if (pick) {
      closeSuggestions();
      if (pathArming) {
        if (pathOwnedMode) { if (!owned.has(pick.id)) { runPathOwned(pick.id); searchInput.blur(); return; } }
        else if (pathFrom && pick.id !== pathFrom) { runPath(pathFrom, pick.id); searchInput.blur(); return; }
      }
      selectNode(pick.id);
      searchInput.blur();
    }
    return;
  } else if (e.key === 'Escape') {
    closeSuggestions();
    if (pathArming) { disarmPath(); toast('Path query cancelled'); return; }
    searchInput.blur();
    return;
  }
  else return;
  items.forEach((el, i) => el.classList.toggle('active', i === sugIndex));
  if (items[sugIndex]) items[sugIndex].scrollIntoView({ block: 'nearest' });
});

searchClear.onclick = () => {
  searchInput.value = '';
  searchClear.style.display = 'none';
  closeSuggestions();
  searchInput.focus();
};

document.addEventListener('click', (e) => {
  if (!e.target.closest('.search-wrap')) closeSuggestions();
});

/* ── keyboard shortcuts ──────────────────────────────────────── */
const helpModal = document.getElementById('helpModal');
function toggleHelp(force) {
  const show = force !== undefined ? force : helpModal.hidden;
  helpModal.hidden = !show;
  if (show) closeSuggestions();
}
document.getElementById('helpBtn').onclick = () => toggleHelp();
document.getElementById('helpClose').onclick = () => toggleHelp(false);
helpModal.addEventListener('click', (e) => { if (e.target === helpModal) toggleHelp(false); });

document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && !helpModal.hidden) { toggleHelp(false); return; }
  if (e.target === searchInput || e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;
  if (e.key === '/') { e.preventDefault(); searchInput.focus(); searchInput.select(); }
  else if (e.key === '?') { e.preventDefault(); toggleHelp(); }
  else if (e.key === 'Escape') { if (pathArming) { disarmPath(); toast('Path query cancelled'); } if (lastPath) clearPath(); if (isolatedRoot) clearIsolation(); closePanel(); clearTrace(); }
  else if (e.key === 'f' || e.key === 'F') cy.fit(undefined, 60);
});

/* ═══════════════════════════════════════════════════════════════
   MINIMAP
   ═══════════════════════════════════════════════════════════════ */
const minimap = document.getElementById('minimap');
minimap.hidden = false;
const mmCanvas = document.getElementById('mmCanvas');
const mmViewport = document.getElementById('mmViewport');
const mmCtx = mmCanvas.getContext('2d');
let mmDirty = true;

function mmResize() {
  const r = minimap.getBoundingClientRect();
  mmCanvas.width = r.width * devicePixelRatio;
  mmCanvas.height = r.height * devicePixelRatio;
  mmDirty = true;
}
window.addEventListener('resize', mmResize);
mmResize();

function drawMinimap() {
  if (mmDirty) {
    mmCtx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
    mmCtx.clearRect(0, 0, mmCanvas.width, mmCanvas.height);
    const w = mmCanvas.width / devicePixelRatio, h = mmCanvas.height / devicePixelRatio;
    const bb = cy.nodes(':visible').boundingBox({});
    if (bb && bb.w > 0) {
      const scale = Math.min((w - 8) / bb.w, (h - 8) / bb.h);
      const ox = (w - bb.w * scale) / 2 - bb.x1 * scale;
      const oy = (h - bb.h * scale) / 2 - bb.y1 * scale;
      for (const n of cy.nodes(':visible')) {
        const p = n.position();
        mmCtx.fillStyle = n.hasClass('locked') ? '#333' : nodeColor(n.data('meta'));
        mmCtx.globalAlpha = n.hasClass('locked') ? 0.25 : 0.75;
        mmCtx.fillRect(ox + p.x * scale - 1, oy + p.y * scale - 1, 2.2, 2.2);
      }
      mmCtx.globalAlpha = 1;
      const extent = cy.extent();
      mmViewport.style.left = (ox + extent.x1 * scale) + 'px';
      mmViewport.style.top = (oy + extent.y1 * scale) + 'px';
      mmViewport.style.width = (extent.w * scale) + 'px';
      mmViewport.style.height = (extent.h * scale) + 'px';
    }
    mmDirty = false;
  }
}

cy.on('position resize add remove', () => { mmDirty = true; });
cy.on('viewport', () => { mmDirty = true; });
(function mmLoop() { drawMinimap(); requestAnimationFrame(mmLoop); })();
minimap.onclick = (e) => {
  const rect = minimap.getBoundingClientRect();
  const bb = cy.nodes(':visible').boundingBox({});
  if (!bb || bb.w <= 0) return;
  const w = rect.width, h = rect.height;
  const scale = Math.min((w - 8) / bb.w, (h - 8) / bb.h);
  const ox = (w - bb.w * scale) / 2 - bb.x1 * scale;
  const oy = (h - bb.h * scale) / 2 - bb.y1 * scale;
  const wx = (e.clientX - rect.left - ox) / scale;
  const wy = (e.clientY - rect.top - oy) / scale;
  cy.animate({ center: { x: wx, y: wy } }, { duration: 300 });
};

/* ── boot ────────────────────────────────────────────────────── */
persistOwned();
applyPossessions();
updateReadout();
console.log(`Dragonwilds Crafting Atlas: ${D.nodes.length} nodes, ${D.edges.length} edges, ${D.recipes.length} recipes`);
